example_item.example_item_data:
% The frontal axis and the global intervals of a simulated twelve-lead record.
recording = ecglab.simulate('Seconds', 20, 'Rate', 500, 'Leads', 12, 'Seed', 1);
result = ecglab.leads(recording);
result.axis.degrees

% The limb leads derived from I and II, and the PR, QRS and QT beside their ranges.
recording = ecglab.simulate('Seconds', 20, 'Rate', 500, 'Leads', {'I', 'II'}, 'Seed', 1);
result = ecglab.leads(recording);
result.derived.leads
result.normal
